@startuml

enum RoomType {
  SINGLE
  DOUBLE
  TWIN
}

enum BookingStatus {
  CONFIRMED
  CANCELLED_BY_TRAVELLER
  CANCELLED_BY_HOTEL
}

enum PaymentType {
  PRE_PAID
  PAID_AT_HOTEL
}

class Traveller {
  + name : string
  + reliabilityRating : int
}

class BillingInformation {
  + companyName : string
  + address : string
}

class TravelPreference {
  + preference : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : RoomType
  + minimumHotelRating : int
  + tentativeBudget : float
}

class Booking {
  + bookingIdentifier : string
  + cancellationDeadline : date
  + bookingStatus : BookingStatus
  + paymentType : PaymentType
}

class Hotel {
  + address : string
  + city : string
}

class HotelChain {}

class SpecialOffer {}

class HBMS {}

Traveller "1" *-- "1" BillingInformation
Traveller "1" *-- "*" TravelPreference
Traveller "1" -- "*" SearchCriteria
Traveller "1" -- "*" Booking

Booking "1" -- "1" SearchCriteria : uses
Booking "1" -- "1" Hotel : confirmed by
Hotel "0..1" -- "1" HotelChain : run by
Hotel "1" -- "*" SpecialOffer : provides
SpecialOffer "*" -- "1" Booking : for

HBMS "1" -- "*" Traveller : manages
HBMS "1" -- "*" Hotel : lists
HBMS "1" -- "*" SpecialOffer : sends

@enduml

